                list.add(current);
            }
        }
        if (current > limit) return;
        generateLucky(current * 10 + 4, limit, list);
        generateLucky(current * 10 + 7, limit, list);
    }

    static boolean isLucky(long num) {
        if (num <= 0) return false;
