            if (d != 4 && d != 7) return false;
            num /= 10;
        }
        return true;
    }

    static long factorial(long n) {
        if (n <= 0) return 1;
        long res = 1;
        for (long i = 2; i <= n; i++) {
            res *= i;
            if (res > 1000000000L) return res; // cap it
        }
        return res;
    }

    static long findKthSmallestUnused(long kth, Set<Long> used, long n) {
